import { task, logger } from '@trigger.dev/sdk/v3'
import { createClient } from '@supabase/supabase-js'
import { processUrl } from '../lib/take-screenshot'

export const runSingleUrlTask = task({
  id: 'run-single-url',
  maxDuration: 120,
  run: async (payload: { urlId: string }) => {
    const supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY!
    )

    const { data: monUrl, error } = await supabase
      .from('monitored_urls')
      .select('*')
      .eq('id', payload.urlId)
      .single()

    if (error || !monUrl) {
      throw new Error(`URL not found: ${payload.urlId}`)
    }

    if (!monUrl.is_active) {
      throw new Error(`URL is paused: ${monUrl.url}`)
    }

    logger.info('Manual run started', { url: monUrl.url })

    const result = await processUrl({ ...monUrl, _manual: true }, supabase)

    logger.info('Manual run complete', {
      url:     monUrl.url,
      diffPct: result.diffPct != null ? `${result.diffPct.toFixed(1)}%` : 'first run',
      alerted: result.alerted,
    })

    return result
  },
})
